#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;

    const long long MOD = 1000000007;
    vector<vector<long long>> dp(2 * n + 1, vector<long long>(2 * n + 1, 0));

    dp[1][1] = 1;

    for (int i = 2; i <= 2 * n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j > 0) {
                dp[i][j] += dp[i - 1][j - 1];
                dp[i][j] %= MOD;
            }
            if (j < 2 * n) {
                dp[i][j] += dp[i - 1][j + 1];
                dp[i][j] %= MOD;
            }
        }
    }

    long long total = 0;
    for (int i = 2 * n - 1; i >= 0; i -= 2) {
        for (int j = 0; j <= i; j++) {
            if (2 * n - i >= j) {
                total += dp[i][j];
                total %= MOD;
            }
        }
    }
    cout << total << "\n";

    return 0;
}
